INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('fault:FAULT-36','fault','RTC / CMOS','Data i godzina resetują się','Date and time reset','symptom: Zegar wraca do daty domyślnej, ustawienia UEFI resetują się po odłączeniu zasilania. focus: Wyklucz synchronizację systemową i sprawdź zależność od odłączenia zasilania. causes: Zużyta bateria RTC/CMOS; nieprawidłowy kontakt lub przewód; problem układu RTC; utrata ustawień NVRAM; błąd firmware lub zasilania podtrzymującego. checks: 1) Sprawdź, czy czas resetuje się także przy działającym systemie. 2) Włącz synchronizację czasu i porównaj z zegarem sieciowym. 3) Zapisz, które ustawienia UEFI wracają. 4) Sprawdź, czy reset następuje po odłączeniu zasilania. steps: 1) Rozdziel problem synchronizacji OS od utraty podtrzymania RTC. 2) Zidentyfikuj typ baterii RTC i sposób montażu dla modelu. 3) Technik sprawdza napięcie baterii i kontakt zgodnie z dokumentacją. 4) Jeśli bateria jest prawidłowa, analizuje tor RTC, EC i NVRAM. 5) Po naprawie zapisuje ustawienia firmware. tests: Wartość i rodzaj baterii nie są uniwersalne; w niektórych laptopach RTC jest połączone z baterią główną albo ma własny przewód. Sprawdź dokumentację i polaryzację. repair: Wymień baterię RTC na część o właściwym typie i złączu; napraw kontakt lub tor RTC, jeżeli to on jest winny. Nie zwieraj pól baterii i nie odwracaj polaryzacji. verify: Odłącz zasilanie zgodnie z procedurą, sprawdź zachowanie ustawień po ponownym starcie i zweryfikuj poprawność daty/czasu oraz Secure Boot/boot order. stop: Przerwij przy spuchniętej, wyciekającej baterii lub nieznanej polaryzacji złącza.','symptomEn: Clock returns to a default date or UEFI settings reset after power is removed. focusEn: Rule out OS time sync and check whether the reset follows power removal. causesEn: Weak RTC/CMOS battery; poor contact or cable; RTC circuit issue; NVRAM settings loss; firmware or standby-power fault. checksEn: 1) Check whether time resets while OS is running. 2) Enable time sync and compare with network time. 3) Record which UEFI settings revert. 4) Check whether reset follows power removal. stepsEn: 1) Separate OS time-sync issue from RTC backup loss. 2) Identify RTC battery type and mounting for the exact model. 3) A technician tests battery voltage and contact per documentation. 4) If battery is good, inspect RTC, EC and NVRAM. 5) Save firmware settings after repair. testsEn: Battery type and value are not universal; some laptops combine RTC with the main battery or use a wired pack. Check documentation and polarity. repairEn: Replace RTC battery with the correct type and connector; repair the RTC path/contact if confirmed faulty. Never short battery pads or reverse polarity. verifyEn: Disconnect power per procedure, check settings retention after restart and verify date/time, Secure Boot and boot order. stopEn: Stop for swollen/leaking battery or unknown connector polarity.','',''),
('fault:FAULT-37','fault','Sieć przewodowa','Nie działa połączenie przewodowe LAN','Wired Ethernet connection fails','symptom: Brak linku, ograniczona łączność lub duże straty połączenia. focus: Sprawdź kabel, port routera i kontrolki linku; porównaj inną sieć. causes: Tryb samolotowy lub przełącznik radiowy; router/AP; błędne hasło; sterownik; usługa systemowa; oszczędzanie energii; antena lub karta Wi-Fi; DHCP/DNS/WAN. checks: 1) Sprawdź tryb samolotowy i fizyczny przełącznik. 2) Porównaj telefon w tej samej sieci. 3) Sprawdź laptop w innej sieci. 4) Zapisz komunikat błędu i siłę sygnału. 5) Uruchom ponownie router tylko po zapisaniu jego statusu i upewnieniu się, że nie wykonuje aktualizacji. steps: 1) Ustal, czy problem dotyczy jednej sieci, wszystkich sieci czy samej karty. 2) Sprawdź Menedżer urządzeń i kod urządzenia. 3) Przywróć właściwy sterownik z witryny producenta po zidentyfikowaniu karty. 4) Sprawdź adres IP, bramę i DNS. 5) Jeśli sygnał jest słaby w kilku lokalizacjach, technik sprawdza anteny i przewody. tests: Zapisz wynik ipconfig /all, ping do bramy i rozpoznawanie nazw DNS. Nie wyłączaj zabezpieczeń routera ani zapory jako „testu” na stałe. repair: Popraw ustawienia sieci, hasło, sterownik lub konfigurację routera. Kartę/antenę wymieniaj dopiero po potwierdzeniu sprzętowym i zgodności z platformą. verify: Sprawdź połączenie po restarcie, transfer pliku, roaming, DNS i stabilność przez kilka minut w zwykłym miejscu użytkowania. stop: Przerwij przy uszkodzonym złączu antenowym, śladach cieczy lub konieczności otwarcia zasilacza/routera. Nie resetuj routera do ustawień fabrycznych bez kopii konfiguracji.','symptomEn: No link, limited connectivity or intermittent packet loss. focusEn: Check cable, router port and link LEDs; compare another network. causesEn: Airplane mode or radio switch; router/AP; incorrect password; driver; OS service; power saving; antenna or Wi-Fi card; DHCP/DNS/WAN. checksEn: 1) Check airplane mode and physical switch. 2) Compare a phone on the same network. 3) Test the laptop on another network. 4) Record error message and signal strength. 5) Restart the router only after recording its status and confirming it is not updating. stepsEn: 1) Determine whether the problem affects one network, all networks or the adapter itself. 2) Check Device Manager and device code. 3) Install the correct vendor driver after identifying the adapter. 4) Check IP address, gateway and DNS. 5) If signal is weak in multiple locations, a technician inspects antennas and cables. testsEn: Record ipconfig /all, gateway ping and DNS resolution. Do not permanently disable router security or firewall as a “test”. repairEn: Correct network settings, password, driver or router configuration. Replace adapter/antenna only after hardware confirmation and platform compatibility check. verifyEn: Check connection after restart, file transfer, roaming, DNS and stability for several minutes in the normal use location. stopEn: Stop for damaged antenna connector, liquid traces or any need to open a PSU/router. Do not factory-reset a router without configuration backup.','',''),
('fault:FAULT-38','fault','Kamera i prywatność','Kamera nie działa','Camera does not work','symptom: Aplikacja nie widzi kamery, obraz jest czarny albo urządzenie jest zajęte. focus: Sprawdź fizyczną przesłonę, uprawnienia prywatności i wybór kamery w aplikacji. causes: Fizyczna przesłona; uprawnienia prywatności; zajęcie kamery przez inną aplikację; sterownik; kabel kamery; moduł kamery; wyłącznik sprzętowy. checks: 1) Otwórz przesłonę. 2) Sprawdź przełącznik/przycisk prywatności. 3) Nadaj uprawnienia aplikacji. 4) Zamknij inne programy korzystające z kamery. 5) Przetestuj kamerę w aplikacji systemowej. steps: 1) Zapisz kod urządzenia w Menedżerze urządzeń. 2) Sprawdź sterownik ze strony producenta. 3) Jeśli kamera znika całkowicie, technik kontroluje przewód/moduł po odłączeniu baterii. 4) Porównaj działanie w UEFI/diagnostyce producenta, jeśli dostępna. 5) Nie podawaj zasilania bez identyfikacji pinów. tests: Wewnętrzna kamera może być podłączona do USB, ale złącza i pinout zależą od konstrukcji. Nie stosuj schematu z innego laptopa. repair: Odblokuj przesłonę i uprawnienia, popraw sterownik, a uszkodzony przewód/moduł wymień po potwierdzeniu numeru części i zgodności. verify: Sprawdź obraz i mikrofon w dwóch aplikacjach, działanie przesłony oraz brak błędów po restarcie. stop: Przerwij przy zalaniu, uszkodzonym przewodzie, uszkodzonym ekranie lub konieczności nieznanego pomiaru na złączu.','symptomEn: App cannot see the camera, image is black or device is busy. focusEn: Check the physical shutter, privacy permissions and camera selection in the app. causesEn: Physical shutter; privacy permissions; camera occupied by another app; driver; camera cable; camera module; hardware switch. checksEn: 1) Open the shutter. 2) Check privacy switch/button. 3) Grant app permissions. 4) Close other apps using camera. 5) Test with the OS camera app. stepsEn: 1) Record Device Manager code. 2) Check the vendor driver. 3) If camera disappears completely, a technician inspects cable/module after disconnecting battery. 4) Compare in UEFI/vendor diagnostics if available. 5) Never apply power without identifying pins. testsEn: An internal camera may use USB, but connector and pinout vary by design. Do not use a schematic from another laptop. repairEn: Unlock shutter and permissions, correct driver, and replace cable/module only after confirming part number and compatibility. verifyEn: Test image and microphone in two apps, shutter operation and no errors after restart. stopEn: Stop for liquid damage, damaged cable, damaged display or unknown connector measurements.','',''),
('fault:FAULT-39','fault','Audio i mikrofon','Mikrofon nagrywa bardzo cicho','Microphone recording is very quiet','symptom: Niski poziom wejścia, szum lub brak głosu w jednej aplikacji. focus: Wybierz właściwe urządzenie wejściowe i wykonaj próbę w systemowym rejestratorze. causes: Złe urządzenie domyślne; wyciszenie; uprawnienia; poziom wejścia; sterownik audio; gniazdo jack; uszkodzony przewód głośnika; kodek audio lub układ na płycie. checks: 1) Sprawdź głośność i wyciszenie. 2) Wybierz prawidłowe wyjście/wejście. 3) Porównaj słuchawki, głośniki i mikrofon zewnętrzny. 4) Sprawdź uprawnienia mikrofonu. 5) Wykonaj próbę w drugiej aplikacji. steps: 1) Oddziel problem całego systemu od jednej aplikacji. 2) Sprawdź Menedżer urządzeń i wersję sterownika. 3) Wyłącz na próbę efekty audio, zapisując stan poprzedni. 4) Technik sprawdza gniazdo, przewody i kodek na schemacie. 5) Porównaj działanie przed i po wznowieniu z uśpienia. tests: Test mikrofonu wykonuj z prawidłowym urządzeniem i poziomem wejścia; sprawdź też fizyczny przełącznik mute w zestawie słuchawkowym. repair: Przywróć właściwe urządzenie, ustawienia lub sterownik. Wymieniaj jack/głośnik/mikrofon lub naprawiaj układ dopiero po porównaniu z urządzeniem zewnętrznym. verify: Zapisz próbkę, odtwórz dźwięk przez każdy tor, sprawdź mikrofon w rozmowie i brak trzasków po restarcie. stop: Przerwij przy zalaniu, zwarciu, nadpalonym jacku lub nietypowym nagrzewaniu.','symptomEn: Low input level, noise or no voice in one application. focusEn: Select the correct input device and test with the OS recorder. causesEn: Wrong default device; mute; permissions; input level; audio driver; jack; damaged speaker cable; audio codec or board circuit. checksEn: 1) Check volume and mute. 2) Select the correct output/input. 3) Compare headphones, speakers and an external microphone. 4) Check microphone permissions. 5) Test in another app. stepsEn: 1) Separate system-wide failure from one app. 2) Check Device Manager and driver version. 3) Temporarily disable audio effects while recording original settings. 4) A technician checks jack, cables and codec using the schematic. 5) Compare operation before and after wake. testsEn: Test the microphone with the correct input and gain; also check the headset’s physical mute switch. repairEn: Restore the correct device, settings or driver. Replace jack/speaker/microphone or repair the codec only after comparison with an external device. verifyEn: Record a sample, play through each output path, test the microphone in a call and confirm no crackle after restart. stopEn: Stop for liquid damage, short circuit, burnt jack or abnormal heating.','',''),
('fault:FAULT-40','fault','Szyfrowanie i dane','Windows prosi o klucz odzyskiwania BitLocker','Windows asks for a BitLocker recovery key','symptom: System żąda 48-cyfrowego klucza po zmianie firmware, TPM, Secure Boot lub sprzętu. focus: Nie czyść TPM i nie formatuj dysku. Najpierw znajdź właściwy klucz odzyskiwania. causes: Zmiana TPM, UEFI/Secure Boot, trybu rozruchu, firmware, płyty głównej lub polityki organizacji; błędna kolejność startu. checks: 1) Zapisz identyfikator klucza wyświetlany na ekranie. 2) Znajdź klucz odzyskiwania w koncie Microsoft lub systemie organizacji. 3) Sprawdź, czy urządzenie należało do firmy/szkoły. 4) Nie zmieniaj ponownie TPM/Secure Boot przed odzyskaniem dostępu. steps: 1) Porównaj identyfikator klucza z zapisanymi kluczami. 2) Wprowadź wyłącznie klucz pasujący do identyfikatora. 3) Po starcie sprawdź stan ochrony i ostatnie zmiany firmware. 4) Przy komputerze firmowym skontaktuj się z administratorem/Entra/AD. 5) Zanim zmienisz firmware, wykonaj kopię danych i zapisz stan ochrony. tests: Nigdy nie czyść TPM, nie kasuj Secure Boot keys i nie formatuj dysku jako metody obejścia BitLocker. Recovery key jest poufny — nie wysyłaj go osobom postronnym. repair: Przywróć poprzednią, znaną konfigurację UEFI tylko wtedy, gdy administrator/dokumentacja potwierdza zmianę. Po odzyskaniu dostępu wyjaśnij przyczynę i wykonaj poprawne zawieszenie/odnowienie ochrony zgodnie z procedurą Microsoft/organizacji. verify: Uruchom system po kolejnym restarcie, sprawdź stan BitLocker, kopię klucza i czy TPM/Secure Boot są w oczekiwanej konfiguracji. stop: Jeśli nie ma właściwego klucza, zatrzymaj operacje niszczące dane. Nie ma bezpiecznej metody odtworzenia klucza przez zgadywanie.','symptomEn: System requests a 48-digit key after firmware, TPM, Secure Boot or hardware changes. focusEn: Do not clear TPM or format the drive. Locate the correct recovery key first. causesEn: TPM, UEFI/Secure Boot, boot-mode, firmware, motherboard or organization-policy change; altered boot order. checksEn: 1) Record the key identifier shown on screen. 2) Find the recovery key in the Microsoft account or organization system. 3) Check whether the device belongs to a company/school. 4) Do not change TPM/Secure Boot again before access is recovered. stepsEn: 1) Match the key identifier with stored recovery keys. 2) Enter only the key matching that identifier. 3) After boot, check protection status and recent firmware changes. 4) For managed PCs contact the administrator/Entra/AD. 5) Before firmware changes, back up data and record protection state. testsEn: Never clear TPM, delete Secure Boot keys or format the drive to bypass BitLocker. The recovery key is confidential; do not share it with others. repairEn: Restore a known previous UEFI configuration only if administrator/vendor documentation confirms the change. After access recovery, identify the cause and suspend/resume protection according to Microsoft/organization procedure. verifyEn: Boot again, verify BitLocker status, recovery-key escrow and expected TPM/Secure Boot configuration. stopEn: If the correct key is unavailable, stop destructive operations. There is no safe way to recover it by guessing.','',''),
('fault:FAULT-41','fault','USB-C / stacja dokująca','Stacja dokująca nie wykrywa monitorów','Docking station does not detect monitors','symptom: Brak obrazu z docka, tylko jeden monitor działa lub porty dokujące są niestabilne. focus: Sprawdź obsługę obrazu przez port, moc zasilacza docka, przewód i liczbę ekranów. causes: Uszkodzony kabel/akcesorium; ograniczona funkcja danego portu; zabrudzone lub wygięte styki; zabezpieczenie ESD/TVS; bezpiecznik/polyfuse; kontroler USB/PCH; niewłaściwy adapter lub wersja protokołu. checks: 1) Sprawdź inne akcesorium i znany sprawny kabel. 2) Wypróbuj drugi port. 3) Obejrzyj złącze bez wkładania metalowych przedmiotów. 4) Dla wideo sprawdź wejście i źródło monitora. 5) Dla USB-C potwierdź w specyfikacji obsługę danych, ładowania i obrazu oddzielnie. steps: 1) Zapisz urządzenie, kabel, port i dokładny objaw. 2) Sprawdź wykrywanie w systemie i komunikaty. 3) Technik ogląda styki, mocowanie i ochronę ESD. 4) Schemat wskazuje zasilanie portu, kontroler i linie danych. 5) Nie wykonuj pomiarów na pinach przy niepewnym pinoucie. tests: USB-C/HDMI/USB mają różne pinouty i warianty. Nie zakładaj, że kolory przewodów lub pinout z ogólnej planszy pasują do każdego kabla/gniazda. repair: Wymień uszkodzony kabel/adapter; napraw mechaniczne mocowanie złącza; wymień bezpiecznik lub ochronę dopiero po ustaleniu przyczyny. Uszkodzenia linii sygnałowych i kontrolera wymagają naprawy płyty. verify: Sprawdź kilka cykli podłączania, transfer danych lub obraz, stabilność zasilania oraz brak nagrzewania złącza. stop: Przerwij przy wygiętych pinach, iskrzeniu, nadpaleniu, wodzie lub nagrzewaniu kabla/portu.','symptomEn: No dock display, only one monitor works or dock ports are unstable. focusEn: Check port video support, dock power supply, cable and display count. causesEn: Faulty cable/accessory; port feature limitation; dirty or bent contacts; ESD/TVS protection; fuse/polyfuse; USB/PCH controller; incompatible adapter or protocol version. checksEn: 1) Test another accessory and known-good cable. 2) Try another port. 3) Inspect the connector without inserting metal objects. 4) For video, check monitor input/source. 5) For USB-C, verify data, charging and video capabilities separately in the specification. stepsEn: 1) Record device, cable, port and exact symptom. 2) Check OS detection and messages. 3) A technician inspects contacts, mounting and ESD protection. 4) The schematic identifies port power, controller and data lines. 5) Never probe pins with an uncertain pinout. testsEn: USB-C/HDMI/USB have different pinouts and variants. Do not assume wire colors or a generic chart match every cable/connector. repairEn: Replace a faulty cable/adapter; repair mechanical connector mounting; replace fuse/protection only after identifying the cause. Signal-line or controller damage requires board repair. verifyEn: Check multiple connect cycles, data transfer or video, stable power and no connector heating. stopEn: Stop for bent pins, arcing, burning, liquid or cable/port heating.','',''),
('fault:FAULT-42','fault','Matryca i podświetlenie','Ekran jest bardzo ciemny','Display is extremely dim','symptom: Treść jest widoczna pod latarką lub ekran świeci słabo mimo wysokiej jasności. focus: Porównaj jasność w UEFI i systemie oraz obraz na zewnętrznym monitorze. causes: Jasność/tryb wyświetlania; uszkodzony panel; taśma eDP/LVDS; brak podświetlenia; złącze lub bezpiecznik podświetlenia; GPU/ścieżka obrazu; sterownik; monitor lub kabel. checks: 1) Zwiększ jasność i wyłącz tryb oszczędzania. 2) Sprawdź, czy widać logo/UEFI. 3) Porównaj obraz na zewnętrznym ekranie. 4) Sprawdź wejście monitora i kabel. 5) Nie ruszaj pokrywą, jeżeli obraz reaguje na jej położenie. steps: 1) Ustal, czy problem występuje już w UEFI, czy dopiero po sterowniku. 2) Zapisz wynik testu zewnętrznego monitora. 3) Technik sprawdza złącze panelu, osadzenie i zgodność przewodu po odłączeniu baterii. 4) Schemat identyfikuje linie zasilania panelu/podświetlenia oraz zabezpieczenia. 5) Weryfikuj panel i przewód na modelu zgodnym, nie na podstawie samego kształtu wtyku. tests: Nie podawaj napięć podświetlenia ani pinów eDP uniwersalnie. Pomiar na złączu panelu jest zadaniem technika: niewłaściwa sonda może spowodować zwarcie i uszkodzić panel lub płytę. repair: Najpierw przywróć właściwe ustawienia/sterownik. Części wymieniaj dopiero po potwierdzeniu: kabel, panel, złącze lub element toru podświetlenia. Napraw mocowań i zawiasów nie odkładaj, jeśli przewód jest naprężony. verify: Sprawdź obraz w UEFI i systemie, kilka poziomów jasności, ruch pokrywy w normalnym zakresie, monitor zewnętrzny oraz brak migotania po wybudzeniu. stop: Przerwij przy pękniętej matrycy, odsłoniętym przewodzie, iskrzeniu, nadpalonym złączu lub konieczności pomiaru bez schematu.','symptomEn: Image is visible with a flashlight or screen stays dim at high brightness. focusEn: Compare brightness in UEFI and OS and test an external display. causesEn: Brightness/display mode; faulty panel; eDP/LVDS cable; backlight failure; connector or backlight fuse; GPU/display path; driver; monitor or cable. checksEn: 1) Increase brightness and disable power saving. 2) Check whether logo/UEFI appears. 3) Compare with an external display. 4) Check monitor input and cable. 5) Do not move the lid if image changes with its angle. stepsEn: 1) Determine whether the problem exists in UEFI or only after the driver loads. 2) Record external-monitor results. 3) A technician inspects panel connector, seating and cable compatibility after disconnecting the battery. 4) The schematic identifies panel/backlight power rails and protection. 5) Verify panel and cable compatibility for the exact model, not by connector shape alone. testsEn: Do not assume universal backlight voltages or eDP pins. Panel-connector measurements are technician work; a misplaced probe can short and damage the panel or board. repairEn: First restore correct settings/driver. Replace parts only after confirmation: cable, panel, connector or backlight-stage component. Do not delay hinge/mount repairs if the cable is under tension. verifyEn: Verify image in UEFI and OS, several brightness levels, normal lid movement, external display and no flicker after wake. stopEn: Stop for cracked panel, exposed cable, arcing, burnt connector or any measurement without the exact schematic.','',''),
('fault:FAULT-43','fault','Nośniki i dane','Kopiowanie plików kończy się błędem','File copy operation fails','symptom: Błędy CRC, rozłączenia, zawieszanie transferu lub uszkodzone pliki. focus: Zabezpiecz ważne pliki i ogranicz ponawianie odczytów z podejrzanego nośnika. causes: Zużycie komórek NAND lub problemy kontrolera; błędy firmware; uszkodzony przewód/gniazdo; niekompatybilny interfejs SATA/NVMe; przegrzewanie; błędy systemu plików; zasilanie nośnika. checks: 1) Jeśli dane są ważne, ogranicz testy i zapisy. 2) Zapisz model nośnika i objawy. 3) Sprawdź, czy nośnik jest wykrywany w UEFI i systemie. 4) Zwróć uwagę na odgłosy mechaniczne HDD. 5) Przy stabilnym nośniku wykonaj kopię najważniejszych danych przed testami. steps: 1) Nie uruchamiaj wielokrotnie klikającego HDD. 2) Sprawdź kabel, port i osadzenie nośnika przy odłączonym zasilaniu. 3) Odczytaj SMART narzędziem producenta lub zaufanym narzędziem, nie traktując jednego parametru jako wyroku. 4) Rozróżnij problemy interfejsu, temperatury, firmware i powierzchni. 5) Przy błędach odczytu wykonaj obraz nośnika na inny sprawny dysk, jeśli stan na to pozwala. tests: SMART to wskaźnik, nie gwarancja sprawności. Testy powierzchniowe, benchmark i CHKDSK mogą pogorszyć sytuację niestabilnego nośnika. Przy niezastąpionych danych najpierw konsultacja z odzyskiem danych. repair: Po bezpiecznej kopii: wymień potwierdzony przewód/adapter, popraw montaż lub wymień nośnik. Firmware aktualizuj tylko według instrukcji producenta i przy stabilnym zasilaniu. Nie formatuj, jeśli dane nie są zabezpieczone. verify: Sprawdź ponowne wykrywanie po zimnym starcie, SMART, temperaturę, transfer dużego pliku oraz odczyt kopii. Zweryfikuj kopię przez otwarcie wybranych plików. stop: Przerwij przy klikaniu/stukaniu HDD, zapachu spalenizny, nadmiernym nagrzaniu, znikaniu nośnika podczas odczytu lub danych o dużej wartości.','symptomEn: CRC errors, disconnects, stalled transfer or corrupted files. focusEn: Protect important files and limit repeated reads from a suspect drive. causesEn: NAND wear or controller issues; firmware errors; damaged cable/connector; SATA/NVMe incompatibility; overheating; filesystem errors; drive power problems. checksEn: 1) If data matters, minimize tests and writes. 2) Record drive model and symptoms. 3) Check detection in UEFI and OS. 4) Listen for mechanical HDD noises. 5) For a stable drive, copy critical data before testing. stepsEn: 1) Do not repeatedly power a clicking HDD. 2) Inspect cable, port and seating with power disconnected. 3) Read SMART using vendor or trusted tools; no single field is a complete verdict. 4) Separate interface, thermal, firmware and media faults. 5) For read errors, image the drive to another healthy disk if its condition permits. testsEn: SMART is an indicator, not a guarantee. Surface tests, benchmarks and CHKDSK can worsen an unstable drive. For irreplaceable data, consult a recovery specialist first. repairEn: After a safe backup: replace a confirmed cable/adapter, reseat or replace the drive. Update firmware only per vendor instructions and with stable power. Do not format before data is secured. verifyEn: Check detection after cold boot, SMART, temperature, large-file transfer and backup readability. Verify the backup by opening sample files. stopEn: Stop for HDD clicking/knocking, burning smell, overheating, drive disappearing during reads or high-value data.','',''),
('fault:FAULT-44','fault','BIOS / RTC','Ustawienia UEFI wracają do domyślnych','UEFI settings revert to defaults','symptom: Kolejność boot, Secure Boot lub ustawienia pamięci resetują się samoistnie. focus: Zapisz zmieniane ustawienia oraz okoliczności; sprawdź, czy reset następuje po odłączeniu zasilania. causes: Zużyta bateria RTC/CMOS; nieprawidłowy kontakt lub przewód; problem układu RTC; utrata ustawień NVRAM; błąd firmware lub zasilania podtrzymującego. checks: 1) Sprawdź, czy czas resetuje się także przy działającym systemie. 2) Włącz synchronizację czasu i porównaj z zegarem sieciowym. 3) Zapisz, które ustawienia UEFI wracają. 4) Sprawdź, czy reset następuje po odłączeniu zasilania. steps: 1) Rozdziel problem synchronizacji OS od utraty podtrzymania RTC. 2) Zidentyfikuj typ baterii RTC i sposób montażu dla modelu. 3) Technik sprawdza napięcie baterii i kontakt zgodnie z dokumentacją. 4) Jeśli bateria jest prawidłowa, analizuje tor RTC, EC i NVRAM. 5) Po naprawie zapisuje ustawienia firmware. tests: Wartość i rodzaj baterii nie są uniwersalne; w niektórych laptopach RTC jest połączone z baterią główną albo ma własny przewód. Sprawdź dokumentację i polaryzację. repair: Wymień baterię RTC na część o właściwym typie i złączu; napraw kontakt lub tor RTC, jeżeli to on jest winny. Nie zwieraj pól baterii i nie odwracaj polaryzacji. verify: Odłącz zasilanie zgodnie z procedurą, sprawdź zachowanie ustawień po ponownym starcie i zweryfikuj poprawność daty/czasu oraz Secure Boot/boot order. stop: Przerwij przy spuchniętej, wyciekającej baterii lub nieznanej polaryzacji złącza.','symptomEn: Boot order, Secure Boot or memory settings revert by themselves. focusEn: Record changed settings and circumstances; check whether reset follows power loss. causesEn: Weak RTC/CMOS battery; poor contact or cable; RTC circuit issue; NVRAM settings loss; firmware or standby-power fault. checksEn: 1) Check whether time resets while OS is running. 2) Enable time sync and compare with network time. 3) Record which UEFI settings revert. 4) Check whether reset follows power removal. stepsEn: 1) Separate OS time-sync issue from RTC backup loss. 2) Identify RTC battery type and mounting for the exact model. 3) A technician tests battery voltage and contact per documentation. 4) If battery is good, inspect RTC, EC and NVRAM. 5) Save firmware settings after repair. testsEn: Battery type and value are not universal; some laptops combine RTC with the main battery or use a wired pack. Check documentation and polarity. repairEn: Replace RTC battery with the correct type and connector; repair the RTC path/contact if confirmed faulty. Never short battery pads or reverse polarity. verifyEn: Disconnect power per procedure, check settings retention after restart and verify date/time, Secure Boot and boot order. stopEn: Stop for swollen/leaking battery or unknown connector polarity.','',''),
('fault:FAULT-45','fault','Obudowa i zawiasy','Pokrywa laptopa stawia opór lub pęka','Laptop lid resists movement or cracks','symptom: Trzaski, odklejanie obudowy, nierówna praca zawiasu lub unoszenie palmrestu. focus: Nie otwieraj na siłę; sprawdź, czy nie ma deformacji sugerującej spuchniętą baterię. causes: Zużyty lub skrzywiony zawias; pęknięte inserty/mocowania; odklejona ramka; źle poprowadzona taśma; deformacja palmrestu; spuchnięta bateria. checks: 1) Nie otwieraj pokrywy na siłę. 2) Obejrzyj szczeliny i mocowania. 3) Sprawdź, czy obudowa nie jest wypychana od środka przez baterię. 4) Zapisz, czy opór występuje po jednej stronie. steps: 1) Ustal, czy winny jest zawias, obudowa, wkręty czy mocowania w palmreście. 2) Zidentyfikuj kompletny zestaw części dla modelu. 3) Technik bezpiecznie demontuje panel i prowadzi taśmę poza strefą zgniatania. 4) Naprawia mocowania zgodnie z metodą producenta. 5) Sprawdza, czy zawias porusza się równomiernie bez naprężania przewodu. tests: Nie testuj ruchu zawiasu wielokrotnie, gdy obudowa pęka. Jeśli podejrzewasz baterię, traktuj urządzenie jako potencjalnie niebezpieczne. repair: Wymień potwierdzony zawias, pokrywę lub mocowania; naprawa klejem nie może maskować uszkodzonej baterii ani prowadzić do kolizji z taśmą. verify: Sprawdź równomierny ruch, utrzymanie kąta, brak trzasków, prawidłowe ułożenie przewodu i obraz w różnych położeniach. stop: Przerwij przy spuchniętej baterii, pękniętej matrycy, widocznym przewodzie lub luźnym elemencie mogącym wypaść.','symptomEn: Cracks, case separation, uneven hinge action or palmrest lifting. focusEn: Do not force it; check for deformation that may indicate a swollen battery. causesEn: Worn or bent hinge; cracked inserts/mounts; detached bezel; misrouted cable; palmrest deformation; swollen battery. checksEn: 1) Do not force the lid. 2) Inspect gaps and mounts. 3) Check whether the case is pushed from inside by the battery. 4) Record whether resistance occurs on one side. stepsEn: 1) Identify whether hinge, case, screws or palmrest mounts failed. 2) Identify the complete model-specific parts set. 3) A technician safely removes the panel and routes the cable away from pinch points. 4) Repair mounts using the vendor method. 5) Confirm smooth hinge motion without cable tension. testsEn: Do not repeatedly cycle the hinge when the case is cracking. If battery swelling is suspected, treat the device as potentially hazardous. repairEn: Replace confirmed hinge, lid or mounts; adhesive repair must not mask a damaged battery or create cable interference. verifyEn: Check even motion, angle retention, no cracking, correct cable routing and image at different lid positions. stopEn: Stop for swollen battery, cracked panel, exposed cable or loose part that may fall out.','',''),
('fault:FAULT-46','fault','Dysk i konfiguracja systemu','Nowy dysk widać w UEFI, ale nie w Windows','New drive appears in UEFI but not in Windows','symptom: Firmware wykrywa nośnik, ale nie ma go w Eksploratorze plików. focus: Zobacz Zarządzanie dyskami, lecz nie inicjalizuj ani nie formatuj nośnika, jeśli zawiera dane. causes: Zużycie komórek NAND lub problemy kontrolera; błędy firmware; uszkodzony przewód/gniazdo; niekompatybilny interfejs SATA/NVMe; przegrzewanie; błędy systemu plików; zasilanie nośnika. checks: 1) Jeśli dane są ważne, ogranicz testy i zapisy. 2) Zapisz model nośnika i objawy. 3) Sprawdź, czy nośnik jest wykrywany w UEFI i systemie. 4) Zwróć uwagę na odgłosy mechaniczne HDD. 5) Przy stabilnym nośniku wykonaj kopię najważniejszych danych przed testami. steps: 1) Nie uruchamiaj wielokrotnie klikającego HDD. 2) Sprawdź kabel, port i osadzenie nośnika przy odłączonym zasilaniu. 3) Odczytaj SMART narzędziem producenta lub zaufanym narzędziem, nie traktując jednego parametru jako wyroku. 4) Rozróżnij problemy interfejsu, temperatury, firmware i powierzchni. 5) Przy błędach odczytu wykonaj obraz nośnika na inny sprawny dysk, jeśli stan na to pozwala. tests: SMART to wskaźnik, nie gwarancja sprawności. Testy powierzchniowe, benchmark i CHKDSK mogą pogorszyć sytuację niestabilnego nośnika. Przy niezastąpionych danych najpierw konsultacja z odzyskiem danych. repair: Po bezpiecznej kopii: wymień potwierdzony przewód/adapter, popraw montaż lub wymień nośnik. Firmware aktualizuj tylko według instrukcji producenta i przy stabilnym zasilaniu. Nie formatuj, jeśli dane nie są zabezpieczone. verify: Sprawdź ponowne wykrywanie po zimnym starcie, SMART, temperaturę, transfer dużego pliku oraz odczyt kopii. Zweryfikuj kopię przez otwarcie wybranych plików. stop: Przerwij przy klikaniu/stukaniu HDD, zapachu spalenizny, nadmiernym nagrzaniu, znikaniu nośnika podczas odczytu lub danych o dużej wartości.','symptomEn: Firmware detects the drive, but it is missing from File Explorer. focusEn: Check Disk Management, but do not initialize or format a drive that may contain data. causesEn: NAND wear or controller issues; firmware errors; damaged cable/connector; SATA/NVMe incompatibility; overheating; filesystem errors; drive power problems. checksEn: 1) If data matters, minimize tests and writes. 2) Record drive model and symptoms. 3) Check detection in UEFI and OS. 4) Listen for mechanical HDD noises. 5) For a stable drive, copy critical data before testing. stepsEn: 1) Do not repeatedly power a clicking HDD. 2) Inspect cable, port and seating with power disconnected. 3) Read SMART using vendor or trusted tools; no single field is a complete verdict. 4) Separate interface, thermal, firmware and media faults. 5) For read errors, image the drive to another healthy disk if its condition permits. testsEn: SMART is an indicator, not a guarantee. Surface tests, benchmarks and CHKDSK can worsen an unstable drive. For irreplaceable data, consult a recovery specialist first. repairEn: After a safe backup: replace a confirmed cable/adapter, reseat or replace the drive. Update firmware only per vendor instructions and with stable power. Do not format before data is secured. verifyEn: Check detection after cold boot, SMART, temperature, large-file transfer and backup readability. Verify the backup by opening sample files. stopEn: Stop for HDD clicking/knocking, burning smell, overheating, drive disappearing during reads or high-value data.','',''),
('fault:FAULT-047','fault','Stabilność / zasilanie','Komputer restartuje się podczas grania lub obciążenia','PC restarts during gaming or load','symptom: Komputer wyłącza się lub restartuje po kilku minutach gry albo testu. focus: Rozdziel temperatury, zasilanie, pamięć, GPU i sterownik. causes: Przegrzewanie CPU/GPU/VRM; niestabilny PSU; OC/undervolt; błędy RAM; sterownik; wadliwy przewód zasilający. checks: Zapisz temperatury i zegary; przywróć ustawienia domyślne; sprawdź logi Kernel-Power i WHEA. steps: Testuj kolejno CPU, GPU, RAM i dysk; monitoruj limity temperatury; sprawdź zasilanie i przewody. tests: Jednoczesny test wszystkich podzespołów dopiero po stabilnych testach jednostkowych. repair: Usuń potwierdzone OC, popraw chłodzenie lub wymień potwierdzony wadliwy element. verify: Powtórz scenariusz gry i dłuższy test bez restartów; sprawdź logi. stop: Przerwij przy zapachu spalenizny, dymie lub szybko rosnącej temperaturze.','symptomEn: The PC powers off or restarts after several minutes of gaming or testing. focusEn: Separate thermals, power, memory, GPU and driver causes. causesEn: CPU/GPU/VRM overheating; unstable PSU; overclock/undervolt; RAM errors; driver; faulty power cable. checksEn: Log temperatures and clocks; restore defaults; inspect Kernel-Power and WHEA logs. stepsEn: Test CPU, GPU, RAM and storage separately; monitor thermal limits; inspect PSU and cables. testsEn: Combined stress testing only after individual tests pass. repairEn: Remove confirmed unstable OC, correct cooling or replace a component only after confirmation. verifyEn: Repeat the gaming scenario and extended test without restarts; review logs. stopEn: Stop for burning smell, smoke or rapidly rising temperature.','',''),
('fault:FAULT-048','fault','Bateria i zasilanie','Laptop wyłącza się po odłączeniu zasilacza','Laptop shuts down when AC adapter is unplugged','symptom: Laptop działa na zasilaczu, ale gaśnie po odłączeniu przewodu. focus: Sprawdź baterię, BMS, złącze i tor zasilania baterii. causes: Zużyta bateria; uszkodzony BMS; odłączone złącze; błąd firmware; uszkodzenie płyty. checks: Odczytaj raport kondycji baterii i sprawdź, czy system wykrywa jej pojemność. steps: Obejrzyj baterię bez naciskania; sprawdź status ładowania i zachowanie w BIOS. tests: Testuj na znanej sprawnej, zgodnej baterii wyłącznie po sprawdzeniu bezpieczeństwa. repair: Wymień baterię tylko po potwierdzeniu zużycia i zgodności numeru części. verify: Sprawdź czas pracy, ładowanie i brak nadmiernego nagrzewania. stop: Przerwij przy spuchnięciu, zapachu lub deformacji obudowy.','symptomEn: Laptop runs on AC but shuts down when the adapter is unplugged. focusEn: Check battery, BMS, connector and battery power path. causesEn: Worn battery; failed BMS; disconnected connector; firmware issue; board fault. checksEn: Read the battery health report and check whether the OS detects capacity. stepsEn: Inspect the battery without pressure; check charging status and BIOS behaviour. testsEn: Test with a known-good compatible battery only after a safety inspection. repairEn: Replace the battery only after confirming wear and matching the part number. verifyEn: Verify runtime, charging and absence of abnormal heat. stopEn: Stop for swelling, odour or enclosure deformation.','',''),
('fault:FAULT-049','fault','Dysk / NVMe','SSD NVMe znika z BIOS lub podczas pracy','NVMe SSD disappears from BIOS or during use','symptom: Dysk okresowo znika, system zawiesza się lub pojawiają się błędy I/O. focus: Rozróżnij awarię nośnika, temperaturę, slot, firmware i zasilanie. causes: Awaria SSD; przegrzewanie; uszkodzony slot; problem firmware; płyta lub zasilanie. checks: Zabezpiecz dane; zapisz SMART/NVMe health i temperaturę; sprawdź wykrywanie po zimnym starcie. steps: Nie uruchamiaj testu zapisu; sprawdź montaż i radiator zgodnie z manualem. tests: Jeśli dane są ważne lub dysk niestabilny, wykonaj obraz z obsługą błędów. repair: Wymień potwierdzony wadliwy nośnik lub usuń problem chłodzenia/slotu. verify: Zweryfikuj SMART, temperaturę, transfer i wykrywanie po restarcie. stop: Przerwij wielokrotne testy przy znikaniu nośnika lub krytycznych danych.','symptomEn: The drive intermittently disappears, the system freezes or I/O errors appear. focusEn: Distinguish drive failure, thermal issue, slot, firmware and power. causesEn: SSD failure; overheating; faulty slot; firmware issue; board or power. checksEn: Protect data; save SMART/NVMe health and temperature; check detection after cold boot. stepsEn: Do not run write stress tests; inspect seating and heatsink according to the manual. testsEn: If data is important or the drive is unstable, create an error-tolerant image. repairEn: Replace a confirmed faulty drive or correct cooling/slot issues. verifyEn: Verify SMART, temperature, transfer and detection after reboot. stopEn: Stop repeated testing if the drive disappears or data is critical.','',''),
('fault:FAULT-050','fault','Dysk / SMART','Komunikat SMART: stan dysku ostrzeżenie lub krytyczny','SMART warning or critical drive health alert','symptom: System ostrzega o kondycji dysku albo pojawiają się błędy odczytu. focus: Ustal atrybuty i ryzyko utraty danych; najpierw kopia. causes: Błędy nośnika; realokowane sektory; błędy niekorygowalne; zbyt wysoka temperatura; zużycie NAND. checks: Zapisz model i raport SMART z narzędzia producenta; nie kasuj logu. steps: Zabezpiecz dane; porównaj atrybuty z dokumentacją producenta. tests: Po kopii wykonaj test odczytu tylko jeśli nośnik jest stabilny. repair: Wymień nośnik przy krytycznych lub rosnących błędach; nie „naprawiaj” SMART resetem. verify: Przywróć dane z kopii i wykonaj test nowego nośnika. stop: Przy nietypowych dźwiękach HDD wyłącz dysk i rozważ laboratorium odzysku.','symptomEn: The system warns about drive health or read errors appear. focusEn: Identify attributes and data-loss risk; back up first. causesEn: Media errors; reallocated sectors; uncorrectable errors; high temperature; NAND wear. checksEn: Save model and SMART report from the vendor tool; do not clear logs. stepsEn: Back up data; compare attributes with vendor documentation. testsEn: After backup, run a read test only if the drive is stable. repairEn: Replace the drive for critical or rising errors; do not attempt to reset SMART. verifyEn: Restore data from backup and test the replacement drive. stopEn: For unusual HDD noises, power it off and consider a recovery lab.','',''),
('fault:FAULT-051','fault','Windows / rozruch','Windows wyświetla „No bootable device”','Windows displays “No bootable device”','symptom: Firmware nie znajduje urządzenia startowego lub nie uruchamia Windows. focus: Rozdziel niewidoczny dysk, kolejność bootowania i uszkodzenie EFI/BCD. causes: Dysk nie jest wykrywany; zmieniony tryb UEFI; uszkodzona partycja EFI; wpis boot; awaria nośnika. checks: Sprawdź, czy dysk jest widoczny w BIOS i zapisz aktualny tryb UEFI. steps: Zabezpiecz klucz BitLocker; sprawdź SMART i układ partycji z WinRE. tests: Wykonaj kopię danych, następnie dobierz naprawę do GPT/UEFI lub MBR/Legacy. repair: Napraw wpis startowy lub wymień dysk po potwierdzeniu przyczyny. verify: Sprawdź kilka zimnych startów i integralność danych. stop: Nie instaluj systemu od nowa, jeśli dane nie są zabezpieczone.','symptomEn: Firmware cannot find a boot device or Windows does not start. focusEn: Separate missing drive, boot order and EFI/BCD damage. causesEn: Drive not detected; changed UEFI mode; damaged EFI partition; boot entry; drive failure. checksEn: Check whether BIOS sees the drive and record the current UEFI mode. stepsEn: Secure the BitLocker key; inspect SMART and partition layout from WinRE. testsEn: Back up data, then choose repair for GPT/UEFI or MBR/Legacy. repairEn: Repair the boot entry or replace the drive after confirming the cause. verifyEn: Verify several cold boots and data integrity. stopEn: Do not reinstall the OS before data is secured.','',''),
('fault:FAULT-052','fault','POST / płyta','Komputer zatrzymuje się na logo producenta','PC hangs at manufacturer logo','symptom: Komputer zatrzymuje się na ekranie logo lub długo przechodzi POST. focus: Ustal urządzenie lub etap inicjalizacji blokujący start. causes: Urządzenie USB; RAM; dysk; BIOS; karta PCIe; ustawienia firmware. checks: Odłącz urządzenia zewnętrzne; sprawdź diody POST i komunikaty firmware. steps: Uruchom konfigurację minimalną i dołączaj urządzenia pojedynczo. tests: Sprawdź pamięć i dyski poza systemem; nie zmieniaj kilku ustawień naraz. repair: Napraw lub wymień tylko potwierdzony element; przywróć udokumentowane ustawienia. verify: Zweryfikuj start z pełną konfiguracją i brak nowych błędów. stop: Przerwij przy sygnałach zwarcia lub nadmiernym grzaniu.','symptomEn: The PC stalls at the logo screen or POST takes unusually long. focusEn: Identify the device or initialization stage blocking startup. causesEn: USB device; RAM; drive; BIOS; PCIe card; firmware settings. checksEn: Disconnect peripherals; inspect POST LEDs and firmware messages. stepsEn: Boot a minimal configuration and add devices one at a time. testsEn: Test memory and drives outside the OS; do not change multiple settings at once. repairEn: Repair or replace only a confirmed component; restore documented settings. verifyEn: Verify boot with the full configuration and no new errors. stopEn: Stop for signs of a short or overheating.','',''),
('fault:FAULT-053','fault','RAM / płyta główna','Pamięć RAM nie jest wykrywana w jednym slocie','RAM is not detected in one memory slot','symptom: Moduł działa w jednym slocie, ale drugi nie wykrywa pamięci. focus: Oddziel uszkodzenie modułu, slotu, gniazda CPU i kontrolera pamięci. causes: Zabrudzony/uszkodzony slot; wygięte piny socketu; problem CPU/IMC; BIOS; niezgodna obsada. checks: Sprawdź instrukcję obsady i testuj ten sam moduł w różnych slotach. steps: Przy odłączonym zasilaniu obejrzyj slot i okolice CPU bez dotykania styków. tests: Zapisz konfigurację i wykonaj test przy ustawieniach JEDEC. repair: Popraw montaż lub wymień wadliwy moduł; naprawa slotu/gniazda wymaga specjalisty. verify: Testuj wszystkie obsługiwane sloty i wykonaj długi test RAM. stop: Nie wkładaj modułu z uszkodzonymi stykami ani nie prostuj pinów bez kwalifikacji.','symptomEn: A DIMM works in one slot but another slot does not detect memory. focusEn: Separate DIMM, slot, CPU socket and memory-controller faults. causesEn: Dirty/damaged slot; bent socket pins; CPU/IMC issue; BIOS; unsupported population. checksEn: Check slot population rules and test the same DIMM in different slots. stepsEn: With power disconnected, inspect the slot and CPU area without touching contacts. testsEn: Record the configuration and test at JEDEC defaults. repairEn: Reseat or replace the faulty DIMM; slot/socket repair requires a specialist. verifyEn: Test all supported slots and run an extended memory test. stopEn: Do not insert a DIMM with damaged contacts or straighten pins without qualification.','',''),
('fault:FAULT-054','fault','GPU / grafika','Artefakty graficzne pojawiają się po rozgrzaniu GPU','GPU artifacts appear after warm-up','symptom: Po kilku minutach pojawiają się kwadraty, pasy, migotanie lub reset sterownika. focus: Oddziel temperaturę, VRAM, sterownik, zasilanie i tor obrazu. causes: Przegrzewanie; VRAM; sterownik; niestabilne OC; kabel/monitor; zasilanie GPU. checks: Sprawdź inny kabel/monitor i przywróć ustawienia GPU domyślne. steps: Monitoruj hotspot, pamięć, moc i logi; wykonaj krótki test VRAM. tests: Porównaj wyniki na innym systemie lub znanej sprawnej karcie. repair: Popraw chłodzenie lub wymień kartę dopiero po potwierdzeniu usterki. verify: Powtórz test do czasu dłuższego niż typowy czas wystąpienia objawu. stop: Przerwij przy dymie, zapachu lub przegrzewaniu.','symptomEn: Squares, lines, flicker or driver resets appear after several minutes. focusEn: Separate temperature, VRAM, driver, power and display path. causesEn: Overheating; VRAM; driver; unstable OC; cable/monitor; GPU power. checksEn: Try another cable/monitor and restore GPU defaults. stepsEn: Monitor hotspot, memory, power and logs; run a short VRAM test. testsEn: Compare results on another OS or with a known-good GPU. repairEn: Correct cooling or replace the card only after confirming failure. verifyEn: Repeat testing for longer than the usual time to failure. stopEn: Stop for smoke, odour or overheating.','',''),
('fault:FAULT-055','fault','DC-IN / USB-C','Laptop ładuje się tylko pod określonym kątem wtyku','Laptop charges only when the plug is held at an angle','symptom: Ładowanie przerywa się przy poruszeniu przewodem lub wtykiem. focus: Ustal, czy uszkodzony jest przewód, gniazdo czy lutowanie na płycie. causes: Przerwany przewód; zużyta wtyczka; pęknięte gniazdo; zimne luty; uszkodzenie portu. checks: Przestań poruszać wtykiem; sprawdź adapter na innym kompatybilnym urządzeniu. steps: Obejrzyj port i obudowę bez naprężania; sprawdź stabilność z innym przewodem. tests: Po odłączeniu baterii/AC skontroluj gniazdo i mocowanie zgodnie z manualem. repair: Wymień zgodny przewód/gniazdo lub wykonaj naprawę płyty po potwierdzeniu. verify: Sprawdź ładowanie bez poruszania przewodem i temperaturę portu. stop: Przerwij przy iskrzeniu, nadtopieniu lub gorącym porcie.','symptomEn: Charging disconnects when the cable or plug moves. focusEn: Determine whether the cable, jack or board solder joint is faulty. causesEn: Broken cable; worn plug; cracked jack; solder fatigue; damaged port. checksEn: Stop moving the plug; test the adapter on another compatible device. stepsEn: Inspect the port and enclosure without stress; check with another cable. testsEn: After disconnecting battery/AC, inspect the jack and mounting according to the manual. repairEn: Replace a compatible cable/jack or perform board repair after confirmation. verifyEn: Verify stable charging without cable movement and check port temperature. stopEn: Stop for arcing, melting or a hot port.','',''),
('fault:FAULT-056','fault','Sieć / Wi-Fi','Wi-Fi działa wolno tylko na jednym komputerze','Wi-Fi is slow only on one computer','symptom: Inne urządzenia działają prawidłowo, a komputer ma niską prędkość lub duże opóźnienia. focus: Rozdziel kartę, sterownik, anteny, pasmo i konfigurację systemu. causes: Sterownik; antena; pasmo; oszczędzanie energii; zakłócenia; VPN lub oprogramowanie filtrujące. checks: Porównaj test przy routerze i na innej sieci; sprawdź pasmo i szybkość linku. steps: Zaktualizuj sterownik OEM; sprawdź anteny i ustawienia oszczędzania energii. tests: Testuj jedną zmianę naraz, zapisując ping, jitter i prędkość. repair: Popraw antenę, sterownik lub konfigurację po potwierdzeniu przyczyny. verify: Powtórz test w tych samych warunkach i porównaj z innym urządzeniem. stop: Nie zmieniaj konfiguracji zabezpieczeń routera bez zgody administratora.','symptomEn: Other devices work normally while this PC has low speed or high latency. focusEn: Separate adapter, driver, antennas, band and OS configuration. causesEn: Driver; antenna; band; power saving; interference; VPN or filtering software. checksEn: Compare testing near the router and on another network; check band and link speed. stepsEn: Update the OEM driver; inspect antennas and power-saving settings. testsEn: Test one change at a time and record ping, jitter and throughput. repairEn: Correct antenna, driver or configuration after confirming the cause. verifyEn: Repeat the test under the same conditions and compare with another device. stopEn: Do not change router security settings without administrator approval.','',''),
('fault:FAULT-057','fault','BitLocker / TPM','Po aktualizacji BIOS pojawia się ekran BitLocker','BitLocker recovery appears after a BIOS update','symptom: System prosi o klucz odzyskiwania po aktualizacji firmware lub zmianie ustawień UEFI. focus: Potwierdź legalny klucz i ustal zmianę pomiarów TPM/Secure Boot. causes: Zmiana TPM; Secure Boot; boot mode; firmware; kolejność rozruchu. checks: Zapisz identyfikator recovery key; nie fotografuj ani nie wysyłaj samego klucza. steps: Właściciel odczytuje klucz z konta; po odblokowaniu sprawdź stan TPM i ochrony. tests: Nie wyłączaj TPM ani Secure Boot tylko po to, by ukryć monit. repair: Przywróć prawidłową konfigurację i wykonaj restart testowy. verify: Nie obchodź szyfrowania ani nie próbuj pozyskać klucza bez upoważnienia. stop: Verify successful boot, TPM status and no repeated recovery prompt.','symptomEn: The system requests a recovery key after firmware update or UEFI setting changes. focusEn: Verify legitimate key access and identify TPM/Secure Boot measurement changes. causesEn: TPM change; Secure Boot; boot mode; firmware; boot order. checksEn: Record the recovery key ID; do not photograph or send the key itself. stepsEn: The owner retrieves the key from their account; after unlock, check TPM and protection state. testsEn: Do not disable TPM or Secure Boot just to hide the prompt. repairEn: Restore the correct configuration and perform a test reboot. verifyEn: Zweryfikuj poprawny start, status TPM i brak ponownego żądania klucza. stopEn: Do not bypass encryption or attempt to obtain a key without authorization.','',''),
('fault:FAULT-058','fault','Windows / aktualizacje','Windows Update zapętla instalację lub wycofuje zmiany','Windows Update loops or rolls back changes','symptom: Aktualizacja nie kończy się, jest cofana lub system uruchamia się w pętli. focus: Odczytaj KB i kod błędu, sprawdź logi i stan magazynu składników. causes: Brak miejsca; uszkodzone składniki; sterownik; problem dysku/RAM; blokada zgodności. checks: Zabezpiecz dane; zapisz KB, kod i etap niepowodzenia. steps: Sprawdź SMART, wolne miejsce, logi CBS i znane problemy wersji. tests: Użyj WinRE lub oficjalnej procedury usuwania ostatniej aktualizacji, jeśli właściwa. repair: Napraw magazyn składników i aktualizuj po usunięciu przyczyny. verify: Zweryfikuj historię aktualizacji i kilka restartów. stop: Nie resetuj systemu ani nie formatuj dysku przed zabezpieczeniem danych.','symptomEn: An update does not complete, rolls back or causes a boot loop. focusEn: Identify KB and error code, inspect logs and component-store state. causesEn: Low disk space; component corruption; driver; drive/RAM issue; compatibility safeguard. checksEn: Protect data; record KB, code and failure stage. stepsEn: Check SMART, free space, CBS logs and release known issues. testsEn: Use WinRE or the official uninstall-latest-update procedure when appropriate. repairEn: Repair the component store and update after addressing the cause. verifyEn: Verify update history and several reboots. stopEn: Do not reset the OS or format the drive before securing data.','',''),
('fault:FAULT-059','fault','Touchpad / sterownik','Laptop nie wykrywa touchpada po aktualizacji systemu','Laptop touchpad not detected after an OS update','symptom: Touchpad zniknął z systemu albo nie reaguje, ale zewnętrzna mysz działa. focus: Oddziel blokadę Fn, ustawienia, sterownik i złącze. causes: Wyłączony touchpad; sterownik I2C/HID; BIOS; taśma; uszkodzenie modułu. checks: Sprawdź Fn key, ustawienia touchpada i Menedżer urządzeń. steps: Zainstaluj sterowniki OEM chipset/I2C/touchpad; cofnij ostatnią zmianę jako test. tests: Jeśli nadal brak urządzenia, sprawdź taśmę po bezpiecznym odłączeniu baterii. repair: Napraw sterownik lub wymień moduł/taśmę po potwierdzeniu. verify: Sprawdź gesty, kliknięcia, przewijanie i działanie po restarcie. stop: Nie odłączaj taśmy przy podłączonej baterii.','symptomEn: The touchpad disappears or stops responding while an external mouse works. focusEn: Separate Fn toggle, settings, driver and connector issues. causesEn: Disabled touchpad; I2C/HID driver; BIOS; ribbon cable; module fault. checksEn: Check Fn key, touchpad settings and Device Manager. stepsEn: Install OEM chipset/I2C/touchpad drivers; roll back the last change as a test. testsEn: If still missing, inspect the ribbon after safely disconnecting the battery. repairEn: Repair the driver or replace the module/ribbon after confirmation. verifyEn: Verify gestures, clicks, scrolling and operation after reboot. stopEn: Do not disconnect the ribbon while the battery is connected.','',''),
('fault:FAULT-060','fault','Chłodzenie / wentylator','Wentylator laptopa pracuje cały czas na maksimum','Laptop fan runs at maximum speed continuously','symptom: Wentylator jest głośny nawet przy małym obciążeniu lub po uruchomieniu. focus: Sprawdź temperaturę, czujniki, zabrudzenie, firmware i procesy. causes: Zatkany radiator; wysoka CPU load; błędny czujnik; sterownik/BIOS; uszkodzony wentylator. checks: Odczytaj temperatury i procesy; porównaj obroty z BIOS/producentem. steps: Sprawdź wyloty, filtr i wentylator; użyj manuala do demontażu chłodzenia. tests: Po oczyszczeniu sprawdź czujniki i krzywą wentylatora, jeśli jest dostępna. repair: Wymień wentylator tylko po potwierdzeniu hałasu/usterki mechanicznej. verify: Zweryfikuj temperatury i obroty w spoczynku oraz obciążeniu. stop: Przerwij test przy zatrzymanym wentylatorze lub wysokiej temperaturze.','symptomEn: The fan is loud even at low load or immediately after startup. focusEn: Check temperature, sensors, dust, firmware and processes. causesEn: Blocked heatsink; high CPU load; sensor fault; driver/BIOS; faulty fan. checksEn: Read temperatures and processes; compare RPM with BIOS/vendor software. stepsEn: Inspect vents, filter and fan; use the manual for cooling disassembly. testsEn: After cleaning, check sensors and fan curve if available. repairEn: Replace the fan only after confirming mechanical noise/failure. verifyEn: Verify temperatures and RPM at idle and under load. stopEn: Stop testing if the fan stalls or temperatures are high.','',''),
('fault:FAULT-061','fault','Obraz / monitor','Monitor wykrywa komputer, ale pokazuje czarny ekran','Monitor detects the PC but shows a black screen','symptom: Monitor ma podświetlenie, ale brak obrazu lub pokazuje czarny ekran po starcie. focus: Oddziel problem źródła, kabla, EDID, GPU, trybu obrazu i systemu. causes: Niewłaściwe wejście; kabel; odświeżanie; sterownik; GPU; uśpienie monitora. checks: Sprawdź OSD, źródło i komunikat „No Signal”; testuj inny kabel. steps: Użyj bezpiecznego trybu obrazu/trybu awaryjnego i innego wyjścia GPU. tests: Podłącz monitor do innego źródła, a PC do innego monitora. repair: Napraw konfigurację lub wymień część toru obrazu po izolacji. verify: Zweryfikuj rozdzielczość, odświeżanie i działanie po restarcie. stop: Nie rozbieraj monitora ani zasilacza.','symptomEn: The monitor has backlight but no picture or remains black after startup. focusEn: Separate source, cable, EDID, GPU, display mode and OS issues. causesEn: Wrong input; cable; refresh rate; driver; GPU; monitor sleep. checksEn: Check OSD, input and “No Signal”; test another cable. stepsEn: Use safe display mode/safe mode and another GPU output. testsEn: Connect the monitor to another source and the PC to another display. repairEn: Correct configuration or replace the failed signal-path component after isolation. verifyEn: Verify resolution, refresh rate and operation after reboot. stopEn: Do not open the monitor or its power supply.','',''),
('fault:FAULT-062','fault','Matryca / taśma','Laptop ma pasy na ekranie przy poruszaniu pokrywą','Laptop display shows lines when the lid moves','symptom: Pasy lub migotanie zmieniają się podczas ruchu pokrywy. focus: Ustal, czy uszkodzona jest taśma, złącze czy panel. causes: Przetarta taśma w zawiasie; poluzowane złącze; uszkodzony panel; zawias. checks: Zewnętrzny monitor pozwala sprawdzić, czy GPU generuje poprawny obraz. steps: Zaprzestań wielokrotnego poruszania pokrywą; sprawdź zawiasy i manual. tests: Po odłączeniu baterii skontroluj przewód i złącza pod powiększeniem. repair: Wymień dokładnie zgodną taśmę/panel i popraw prowadzenie przewodu. verify: Testuj pełny zakres ruchu pokrywy i obraz po zimnym starcie. stop: Nie podłączaj taśmy przy włączonym laptopie.','symptomEn: Lines or flicker change when the lid moves. focusEn: Determine whether the cable, connector or panel is damaged. causesEn: Abraded hinge cable; loose connector; damaged panel; hinge fault. checksEn: An external monitor helps determine whether the GPU produces a correct image. stepsEn: Stop repeatedly moving the lid; inspect hinges and service manual. testsEn: After disconnecting the battery, inspect cable and connectors under magnification. repairEn: Replace the exact compatible cable/panel and route the cable correctly. verifyEn: Test the full lid movement range and display after cold boot. stopEn: Never connect the cable while the laptop is powered.','',''),
('fault:FAULT-063','fault','USB / porty','Port USB nie działa po podłączeniu urządzenia','USB port stops working after a device is connected','symptom: Port nie wykrywa urządzeń, wyłącza się lub powoduje komunikat o przeciążeniu. focus: Sprawdź urządzenie, przewód, port i zabezpieczenie nadprądowe. causes: Uszkodzony kabel/urządzenie; zwarcie; uszkodzone styki; sterownik; bezpiecznik/limit portu. checks: Odłącz urządzenie i nie podłączaj go ponownie przed inspekcją. steps: Sprawdź peryferium na znanym sprawnym porcie i obejrzyj port bez zasilania. tests: Sprawdź logi USB i zachowanie innych portów. repair: Napraw lub wymień kabel/port po ustaleniu przyczyny przeciążenia. verify: Zweryfikuj port kontrolowanym, sprawnym urządzeniem. stop: Przy zwarciu lub gorącym porcie odłącz zasilanie.','symptomEn: The port does not detect devices, shuts down or reports an overcurrent condition. focusEn: Check peripheral, cable, port and overcurrent protection. causesEn: Faulty cable/peripheral; short; damaged contacts; driver; port fuse/current limit. checksEn: Disconnect the device and do not reconnect it before inspection. stepsEn: Test the peripheral on a known-good port and inspect the port with power removed. testsEn: Inspect USB logs and behaviour of other ports. repairEn: Repair or replace the cable/port after identifying the overcurrent cause. verifyEn: Verify the port with a known-good, low-risk device. stopEn: Disconnect power for a shorted or hot port.','',''),
('fault:FAULT-064','fault','Wi-Fi / sterownik','Komputer nie wykrywa karty Wi-Fi po naprawie','PC does not detect Wi-Fi adapter after repair','symptom: Karta Wi-Fi zniknęła z systemu po demontażu lub aktualizacji. focus: Rozdziel brak modułu, anten, sterownika i ustawień firmware. causes: Moduł niedociśnięty; taśma/antenna; sterownik; BIOS; uszkodzenie slotu. checks: Sprawdź Menedżer urządzeń i identyfikator sprzętu; potwierdź, czy jest nieznane urządzenie. steps: Po odłączeniu baterii skontroluj osadzenie modułu i przewody anten. tests: Zainstaluj sterownik OEM i sprawdź wykrywanie po zimnym starcie. repair: Popraw osadzenie lub wymień zgodny moduł po potwierdzeniu. verify: Zweryfikuj Wi-Fi i Bluetooth oraz jakość połączenia. stop: Nie odłączaj anten przy zasilonym urządzeniu.','symptomEn: The Wi-Fi adapter disappears after disassembly or update. focusEn: Separate module, antenna, driver and firmware setting issues. causesEn: Module not seated; antenna lead; driver; BIOS; slot fault. checksEn: Check Device Manager and hardware ID; see whether an unknown device appears. stepsEn: After disconnecting the battery, inspect module seating and antenna leads. testsEn: Install the OEM driver and check detection after a cold boot. repairEn: Reseat or replace a compatible module after confirmation. verifyEn: Verify Wi-Fi and Bluetooth and connection quality. stopEn: Do not disconnect antennas while powered.','',''),
('fault:FAULT-065','fault','RTC / BIOS','Data i godzina BIOS resetują się po odłączeniu komputera','BIOS date and time reset after the PC is unplugged','symptom: Po odłączeniu zasilania ustawienia zegara wracają do wartości domyślnych. focus: Sprawdź baterię RTC i obwód podtrzymania. causes: Rozładowana bateria; przewód RTC; holder; obwód płyty; ustawienia firmware. checks: Zapisz datę, czas i zachowanie po zimnym starcie. steps: Sprawdź typ baterii i napięcie zgodnie z dokumentacją; nie zwieraj ogniwa. tests: Zmierz napięcie baterii zgodnie z dokumentacją i sprawdź stan holdera. repair: Wymień zgodny element przy odłączonym zasilaniu. verify: Ustaw czas, odłącz AC i potwierdź zachowanie po ponownym uruchomieniu. stop: Nie stosuj baterii o innym typie lub izolacji.','symptomEn: After AC power is disconnected, clock settings reset to defaults. focusEn: Check RTC battery and backup circuit. causesEn: Depleted battery; RTC cable; holder; board circuit; firmware settings. checksEn: Record date, time and behaviour after cold boot. stepsEn: Check battery type and voltage per documentation; do not short the cell. testsEn: Measure battery voltage per documentation and inspect the holder. repairEn: Replace the matching part with power disconnected. verifyEn: Set the clock, disconnect AC and confirm behaviour after restart. stopEn: Do not use a battery with a different type or insulation.','',''),
('fault:FAULT-066','fault','Kamera / mikrofon','Laptop nie uruchamia kamery lub mikrofonu','Laptop camera or microphone does not work','symptom: Kamera/mikrofon nie jest wykrywany albo aplikacja nie otrzymuje sygnału. focus: Sprawdź prywatność, uprawnienia, sterownik, urządzenie i taśmę. causes: Zasłona; skrót prywatności; uprawnienia; sterownik; taśma; moduł. checks: Sprawdź fizyczną zasłonę, uprawnienia i wybrane urządzenie wejściowe. steps: Przetestuj inną aplikację i sprawdź Menedżer urządzeń. tests: Demontuj moduł tylko według instrukcji po odłączeniu baterii. repair: Napraw ustawienia/sterownik lub wymień moduł po potwierdzeniu. verify: Zweryfikuj obraz i dźwięk bez rejestrowania danych użytkownika. stop: Test wymaga zgody użytkownika.','symptomEn: Camera/microphone is not detected or the app receives no input. focusEn: Check privacy settings, permissions, driver, device and cable. causesEn: Shutter; privacy key; permissions; driver; cable; module. checksEn: Check physical shutter, permissions and selected input device. stepsEn: Test another app and inspect Device Manager. testsEn: Remove the module only by manual after battery disconnection. repairEn: Correct settings/driver or replace the module after confirmation. verifyEn: Verify image and audio without recording user data. stopEn: Testing requires user consent.','',''),
('fault:FAULT-067','fault','Audio','Brak dźwięku mimo poprawnego działania Windows','No audio despite Windows working normally','symptom: System działa, ale nie ma dźwięku w głośnikach lub słuchawkach. focus: Sprawdź routing, poziomy, kodek, port i sterownik. causes: Błędne wyjście; wyciszenie; sterownik; kodek; głośniki; jack. checks: Sprawdź poziomy, mikser i urządzenie domyślne. steps: Przetestuj słuchawki i głośniki na innym źródle. tests: Sprawdź sterownik OEM i błędy urządzenia. repair: Napraw routing lub wymień potwierdzony moduł/komponent audio. verify: Testuj głośniki, słuchawki, mikrofon i HDMI. stop: Nie zwieraj styków gniazda audio.','symptomEn: The OS works but speakers or headphones produce no sound. focusEn: Check routing, levels, codec, jack and driver. causesEn: Wrong output; mute; driver; codec; speakers; jack. checksEn: Check levels, mixer and default device. stepsEn: Test headphones and speakers on another source. testsEn: Check OEM driver and device errors. repairEn: Correct routing or replace a confirmed audio module/component. verifyEn: Test speakers, headphones, microphone and HDMI. stopEn: Do not short audio-jack contacts.','',''),
('fault:FAULT-068','fault','Klawiatura / zalanie','Klawiatura laptopa nie działa po zalaniu','Laptop keyboard not working after liquid exposure','symptom: Część klawiszy nie reaguje lub klawiatura działa losowo po zalaniu. focus: Najpierw zabezpiecz płytę i baterię; nie testuj przez kolejne uruchamianie. causes: Korozja; osad przewodzący; uszkodzona taśma; klawiatura; EC. checks: Odłącz zasilanie; zanotuj rodzaj cieczy i obszar zalania. steps: Oceń baterię i płytę; sprawdź złącze po bezpiecznym demontażu. tests: Czyść i naprawiaj dopiero po ocenie korozji i usunięciu zanieczyszczeń. repair: Wymień klawiaturę/taśmę tylko po potwierdzeniu zakresu uszkodzeń. verify: Testuj wszystkie klawisze po bezpiecznym złożeniu. stop: Przerwij przy spuchniętej baterii, dymie lub nagrzewaniu.','symptomEn: Some keys fail or the keyboard behaves erratically after a spill. focusEn: Protect the board and battery first; do not repeatedly power on to test. causesEn: Corrosion; conductive residue; damaged ribbon; keyboard; EC. checksEn: Disconnect power; record liquid type and affected area. stepsEn: Assess battery and board; inspect the connector after safe disassembly. testsEn: Clean and repair only after corrosion assessment and residue removal. repairEn: Replace keyboard/ribbon only after confirming damage extent. verifyEn: Test every key after safe reassembly. stopEn: Stop for a swollen battery, smoke or heat.','',''),
('fault:FAULT-069','fault','Dysk / wydajność','System zwalnia i zawiesza się podczas kopiowania plików','System slows or freezes while copying files','symptom: Kopiowanie plików trwa długo, zawiesza system lub generuje błędy I/O. focus: Oddziel problem źródła, celu, kabla, sterownika i nośnika. causes: Błędy dysku; przegrzewanie SSD; kabel SATA; port USB; RAM; antywirus. checks: Sprawdź SMART obu nośników i użyj małego pliku testowego. steps: Porównaj transfer na innym porcie/kablu i w innej obudowie. tests: Monitoruj temperaturę, kolejkę dysku i błędy systemowe. repair: Wymień potwierdzony przewód/nośnik; zabezpiecz dane przed dalszym testem. verify: Powtórz transfer z sumą kontrolną pliku. stop: Nie wykonuj wielokrotnych testów zapisu na niestabilnym SSD/HDD.','symptomEn: File copying is slow, freezes the system or produces I/O errors. focusEn: Separate source, destination, cable, driver and drive issues. causesEn: Drive errors; SSD overheating; SATA cable; USB port; RAM; antivirus. checksEn: Check SMART on both drives and use a small test file. stepsEn: Compare transfer with another port/cable and enclosure. testsEn: Monitor temperature, disk queue and system errors. repairEn: Replace a confirmed cable/drive; secure data before further testing. verifyEn: Repeat the transfer and verify the file checksum. stopEn: Do not run repeated write tests on an unstable SSD/HDD.','',''),
('fault:FAULT-070','fault','Płyta / TPM / rozruch','Po wymianie płyty komputer żąda klucza BitLocker lub nie startuje','After motherboard replacement, BitLocker recovery or boot failure occurs','symptom: Po wymianie płyty zmienił się TPM, Secure Boot albo konfiguracja startowa. focus: Zabezpiecz klucz i sprawdź kompatybilność oraz konfigurację firmware. causes: Zmiana TPM; UEFI; brak sterownika; niezgodny CPU/RAM; aktywacja; inny tryb SATA. checks: Sprawdź dokumentację nowej płyty i status szyfrowania. steps: Weryfikuj zgodność CPU/RAM/BIOS i ustawienia UEFI bez wyłączania zabezpieczeń na ślepo. tests: Właściciel odblokowuje dysk kluczem; dopiero potem diagnozuj rozruch. repair: Ustaw zgodny tryb i sterowniki oraz napraw start w oparciu o układ partycji. verify: Zweryfikuj start, TPM, Secure Boot, BitLocker i aktywację systemu. stop: Nie omijaj szyfrowania i nie zapisuj klucza w raporcie.','symptomEn: After board replacement, TPM, Secure Boot or boot configuration changed. focusEn: Secure the key and verify compatibility and firmware configuration. causesEn: TPM change; UEFI; missing driver; incompatible CPU/RAM; activation; different SATA mode. checksEn: Check the new board documentation and encryption status. stepsEn: Verify CPU/RAM/BIOS compatibility and UEFI settings without blindly disabling security. testsEn: The owner unlocks the drive with the key; only then diagnose boot. repairEn: Configure compatible mode/drivers and repair boot based on the partition layout. verifyEn: Verify boot, TPM, Secure Boot, BitLocker and OS activation. stopEn: Do not bypass encryption or store the key in the report.','','');
